import{_ as t,o,c as a,ag as d}from"./chunks/framework.BZohXCq9.js";const g=JSON.parse('{"title":"Teacher Dashboard -> Booking Management (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/booking-management.md","filePath":"modules/teacher-dashboard/booking-management.md"}'),n={name:"modules/teacher-dashboard/booking-management.md"};function i(r,e,s,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="teacher-dashboard-booking-management-deep" tabindex="-1">Teacher Dashboard -&gt; Booking Management (deep) <a class="header-anchor" href="#teacher-dashboard-booking-management-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Booking Management (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>booking-management</code><br><strong>Route:</strong> <code>/teacher-dashboard/bookingManagement</code></p><p>This module lets instructors inspect their bookings and update slot status directly from the teacher dashboard.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show all bookings belonging to the instructor.</li><li>Open booking details modal with student/instructor/slot/payment context.</li><li>Update slot status for the instructor’s lessons.</li><li>Keep sidebar booking badge state in sync.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/components/InstructorComponent/StudentBookingWInst.tsx</code></td><td>Main booking-management screen</td><td>Calls <code>GET_INSTRUCTOR_BOOKINGS_BY_ID</code> and <code>UPDATE_SLOT_STATUS</code>; contains confirmation modal, status dropdown, and detail modal.</td></tr><tr><td><code>Frontend/src/graphql/Queries/AdminBookingShowcase.ts</code></td><td>Instructor booking query source</td><td>Defines <code>GET_INSTRUCTOR_BOOKINGS_BY_ID</code>.</td></tr><tr><td><code>Frontend/src/graphql/mutations/studentBooking.ts</code></td><td>Slot-status mutation source</td><td>Defines <code>UPDATE_SLOT_STATUS</code>.</td></tr><tr><td><code>Frontend/src/layouts/TeacherLayout.tsx</code></td><td>Sidebar badge integration</td><td>Clears unseen booking count when this route is visited.</td></tr><tr><td><code>Frontend/src/utils/useBookingNotification.ts</code></td><td>Notification hook</td><td>Drives unseen booking count and socket registration.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-instructor-bookings-by-id" tabindex="-1"><code>GET_INSTRUCTOR_BOOKINGS_BY_ID</code> <a class="header-anchor" href="#get-instructor-bookings-by-id" aria-label="Permalink to &quot;`GET_INSTRUCTOR_BOOKINGS_BY_ID`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/AdminBookingShowcase.ts</code></li><li>Query field: <code>getInstructorBookingsById(instructorId: ID!)</code></li><li>Used by: <code>StudentBookingWInst.tsx</code></li></ul><h3 id="update-slot-status" tabindex="-1"><code>UPDATE_SLOT_STATUS</code> <a class="header-anchor" href="#update-slot-status" aria-label="Permalink to &quot;`UPDATE_SLOT_STATUS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/studentBooking.ts</code></li><li>Mutation field: <code>updateSlotStatus(...)</code></li><li>Used by: <code>StudentBookingWInst.tsx</code></li><li>Responsible for teacher-side status updates</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>Files: <ul><li><code>server/src/graphql/typeDefs/AdminBookingType.js</code></li><li><code>server/src/graphql/typeDefs/studentBooking.typeDefs.js</code></li></ul></li><li>Relevant fields: <ul><li><code>getInstructorBookingsById(instructorId: ID!): [StudentBookingAdmin!]!</code></li><li><code>getInstructorBookings</code></li><li><code>updateSlotStatus</code></li><li><code>updateBookingStatus</code></li><li><code>cancelBookingSlot</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>Files: <ul><li><code>server/src/graphql/resolvers/AdminBookingType.resolver.js</code></li><li><code>server/src/graphql/resolvers/studentBooking.resolver.js</code></li></ul></li><li>Relevant resolvers: <ul><li><code>Query.getInstructorBookingsById</code><ul><li>used by this teacher screen for fetching bookings</li></ul></li><li><code>Mutation.updateSlotStatus</code><ul><li>teacher-side slot-status mutation</li></ul></li><li>related teacher booking mutations: <ul><li><code>updateBookingStatus</code></li><li><code>cancelBookingSlot</code></li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Primary booking source</td></tr><tr><td><code>server/src/models/teacherAvailability.model.js</code></td><td>Synced when slot state changes</td></tr><tr><td><code>server/src/utils/SendOtpEmail.js</code></td><td>Booking-status notifications</td></tr><tr><td><code>server/src/socket/index.js</code></td><td>New-booking notifications and badge-related events</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Teacher opens booking management.</li><li>Screen reads current instructor id from auth context.</li><li><code>GET_INSTRUCTOR_BOOKINGS_BY_ID</code> returns bookings for that instructor.</li><li>Changing slot status opens confirmation and sends <code>UPDATE_SLOT_STATUS</code>.</li><li>Backend updates the booking slot and related availability/notification state.</li><li><code>TeacherLayout.tsx</code> clears unseen booking count when this page is active.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>The fetch query comes from the admin-booking schema (<code>getInstructorBookingsById</code>), while the update mutation comes from the instructor/student-booking schema (<code>updateSlotStatus</code>).</li><li>This cross-module usage is real in the current codebase and is worth preserving in docs because it is not obvious from filenames alone.</li></ul>',23)])])}const b=t(n,[["render",i]]);export{g as __pageData,b as default};
